#include <stdio.h>

int main(void) {
    int m, n, p;
    scanf("%d %d %d", &m, &n, &p);
    int a[50][50], b[50][50];
    long long c[50][50];
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < p; j++)
            scanf("%d", &b[i][j]);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            long long s = 0;
            for (int k = 0; k < n; k++) s += (long long)a[i][k] * b[k][j];
            c[i][j] = s;
        }
    }
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            if (j > 0) printf(" ");
            printf("%lld", c[i][j]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[100][100];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int tmp = a[i][j];
            a[i][j] = a[j][i];
            a[j][i] = tmp;
        }
    }
    for (int i = 0; i < n; i++) {
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int tmp = a[i][lo];
            a[i][lo] = a[i][hi];
            a[i][hi] = tmp;
            lo++;
            hi--;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j > 0) printf(" ");
            printf("%d", a[i][j]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int r, c;
    scanf("%d %d", &r, &c);
    int a[50][50];
    for (int i = 0; i < r; i++)
        for (int j = 0; j < c; j++)
            scanf("%d", &a[i][j]);
    int top = 0, bottom = r - 1, left = 0, right = c - 1;
    int first = 1;
    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; j++) {
            if (!first) printf(" ");
            printf("%d", a[top][j]);
            first = 0;
        }
        top++;
        for (int i = top; i <= bottom; i++) {
            if (!first) printf(" ");
            printf("%d", a[i][right]);
            first = 0;
        }
        right--;
        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                if (!first) printf(" ");
                printf("%d", a[bottom][j]);
                first = 0;
            }
            bottom--;
        }
        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                if (!first) printf(" ");
                printf("%d", a[i][left]);
                first = 0;
            }
            left++;
        }
    }
    printf("\n");
    return 0;
}

